-- Carga inicial das Categorias de Gasto


-- Criacao da tabela tb_saldo
CREATE TABLE IF NOT EXISTS tb_saldo (
    id_saldo BIGSERIAL PRIMARY KEY,
    bloqueado_cheque DOUBLE PRECISION,
    disponivel DOUBLE PRECISION,
    bloqueado_judicialmente DOUBLE PRECISION,
    bloqueado_administrativo DOUBLE PRECISION,
    limite DOUBLE PRECISION,
    data_referencia VARCHAR(255),
    created_at TIMESTAMP WITHOUT TIME ZONE
);
